#!/usr/bin/env python3

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def reconstruct_raid5():
    BLOCK_SIZE = 4096

    print("[+] Starting RAID-5 reconstruction...")
    print("[+] Using block size:", BLOCK_SIZE)

    with open('disk.img0', 'rb') as f0, open('disk.img1', 'rb') as f1, open('recovered.bin', 'wb') as fout:
        block_num = 0
        while True:
            # Read blocks from both disks
            block0 = f0.read(BLOCK_SIZE)
            block1 = f1.read(BLOCK_SIZE)

            # Check if we've reached the end
            if not block0 or not block1:
                break

            # Checkerboard pattern reconstruction:
            # Even blocks: disk0=data, disk1=parity
            # Odd blocks: disk0=parity, disk1=data
            if block_num % 2 == 0:
                # Even block: disk0 is data
                fout.write(block0)
            else:
                # Odd block: disk1 is data
                fout.write(block1)

            block_num += 1

            if block_num % 1000 == 0:
                print(f"[+] Processed {block_num} blocks...")

    print(f"[+] Reconstruction complete! Processed {block_num} total blocks")

if __name__ == "__main__":
    reconstruct_raid5()
